root=Path(__file__).resolve().parents[2];p=root/'research/nine-sharing-sign16-inner-from-seed-check';draft=root/'research/nine-sharing-sign16-inner-from-seed-draft';sha=lambda q:hashlib.sha256(q.read_bytes()).hexdigest();run=p/'run.py';m=p/'source-manifest.json';assert sha(run)=='f5aba82fb1ff0c66128468915f40d49aea81fbd0eef00e0169327a4c73dde009' and sha(m)=='258f2b7bb584f6a3bffe62d51ed5dfb2212626238f541abb7f9cd1cc6698955a';row,=json.loads(m.read_text())['rows'];name='Sign16InnerFromSeed';src=p/'src/DiophantineConsistency'/(name+'.lean');s=src.read_text();assert sha(src)==sha(draft/(name+'.lean'))==row['source_sha256']=='70d4c2d1fcf48f2a12aa774367e83477070b38a0c3bbe9abd52abf73b50ee0ef' and row['module']=='DiophantineConsistency.'+name and re.findall(r'^import ([A-Za-z0-9_.]+)$',s,re.M)==row['imports']==['DiophantineConsistency.Sign16ScalarWindow','DiophantineConsistency.Sign16RankValue','DiophantineConsistency.Sign16RowPremises'];assert not re.search(r'(?m)^\s*(axiom|opaque)\b|\b(sorry|admit)\b',s)
